const taylorQuotes: Quote[] = [
  { id: 't001', text: "I knew you were trouble when you walked in.", source: 'taylor', context: '"I Knew You Were Trouble" — Red (2012)', tone: 'threatening', intensity: 3, ambiguityScore: 7, commentary: "A warning disguised as a confession. The don would frame it the same way." },
  { id: 't002', text: "Don't say I didn't warn ya.", source: 'taylor', context: '"Bad Blood" — 1989 (2014)', tone: 'threatening', intensity: 4, ambiguityScore: 9, commentary: "The last thing said before consequences arrive." },
  { id: 't003', text: "Look what you made me do.", source: 'taylor', context: '"Look What You Made Me Do" — Reputation (2017)', tone: 'vengeful', intensity: 5, ambiguityScore: 10, commentary: "The most Godfather sentence Taylor has ever written." },
  { id: 't004', text: "Bandaids don't fix bullet holes.", source: 'taylor', context: '"Bad Blood" — 1989 (2014)', tone: 'threatening', intensity: 5, ambiguityScore: 10, commentary: "The single most mob-coded lyric in the Swift catalog." },
  { id: 't005', text: "I laid the groundwork and then just like clockwork the dominoes cascaded in a line.", source: 'taylor', context: '"Mastermind" — Midnights (2022)', tone: 'power', intensity: 5, ambiguityScore: 9, commentary: "A criminal mastermind confessing the plot. Or a pop star. Both." },
  { id: 't008', text: "I'm shining like fireworks over your sad, empty town.", source: 'taylor', context: '"Dear John" — Speak Now (2010)', tone: 'vengeful', intensity: 4, ambiguityScore: 6, commentary: "Revenge delivered cinematically from a great height." },
  { id: 't010', text: "I don't trust nobody and nobody trusts me.", source: 'taylor', context: '"I Did Something Bad" — Reputation (2017)', tone: 'power', intensity: 4, ambiguityScore: 9, commentary: "The code of the street. Also the code of a pop star who got burned." },
  { id: 't011', text: "This is the last time I'm asking you this. Put my name at the top of your list.", source: 'taylor', context: '"The Last Time" — Red (2012)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Not a request. A final offer." },
  { id: 't012', text: "Got a long list of ex-lovers, they'll tell you I'm insane.", source: 'taylor', context: '"Blank Space" — 1989 (2014)', tone: 'chaotic', intensity: 4, ambiguityScore: 6, commentary: "A reputation preceding her like a don entering a room." },
  { id: 't013', text: "I can make the bad guys good for a weekend.", source: 'taylor', context: '"Blank Space" — 1989 (2014)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "The power to rehabilitate criminals." },
  { id: 't014', text: "I could build a castle out of all the bricks they threw at me.", source: 'taylor', context: '"New Romantics" — 1989 (2014)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Turning adversity into architecture. Empire-building energy." },
  { id: 't015', text: "They're burning all the witches even if you aren't one.", source: 'taylor', context: '"I Did Something Bad" — Reputation (2017)', tone: 'threatening', intensity: 4, ambiguityScore: 7, commentary: "Mob justice extended to the innocent." },
  { id: 't016', text: "I swear I don't love the drama. It loves me.", source: 'taylor', context: '"I Did Something Bad" — Reputation (2017)', tone: 'chaotic', intensity: 4, ambiguityScore: 6, commentary: "Drama as companion rather than choice." },
  { id: 't017', text: "I want to be your end game.", source: 'taylor', context: '"End Game" — Reputation (2017)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "End game. Final move. Strategic positioning." },
  { id: 't019', text: "I've been the archer. I've been the prey.", source: 'taylor', context: '"The Archer" — Lover (2019)', tone: 'power', intensity: 4, ambiguityScore: 5, commentary: "Duality of hunter and hunted. Michael Corleone's entire arc." },
  { id: 't020', text: "Long live all the mountains we moved.", source: 'taylor', context: '"Long Live" — Speak Now (2010)', tone: 'loyalty', intensity: 4, ambiguityScore: 6, commentary: "The battle cry of an inner circle. Or a family empire." },
  { id: 't022', text: "All I know is I was enchanted to meet you.", source: 'taylor', context: '"Enchanted" — Speak Now (2010)', tone: 'romantic', intensity: 2, ambiguityScore: 3, commentary: "Pure romance. Even the Corleones couldn't make this threatening." },
  { id: 't023', text: "I'm only up when you're not down.", source: 'taylor', context: '"Holy Ground" — Red (2012)', tone: 'loyalty', intensity: 2, ambiguityScore: 4, commentary: "Codependency as devotion. The most human sentence." },
  { id: 't024', text: "Did you have to ruin what was shiny? Now it's all rusted.", source: 'taylor', context: '"Sad Beautiful Tragic" — Red (2012)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "The most devastating metaphor for a relationship ending." },
  { id: 't025', text: "We are never, ever, ever getting back together.", source: 'taylor', context: '"We Are Never Getting Back Together" — Red (2012)', tone: 'power', intensity: 3, ambiguityScore: 3, commentary: "Repetition for emphasis. A negotiating tactic the don would respect." },
  { id: 't028', text: "Long story short I survived.", source: 'taylor', context: '"Long Story Short" — Evermore (2020)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "The understatement of a survivor. Quiet power." },
  { id: 't029', text: "I'm doing better than I ever was.", source: 'taylor', context: '"Cruel Summer" — Lover (2019)', tone: 'power', intensity: 3, ambiguityScore: 4, commentary: "A comeback delivered like a threat." },
  { id: 't030', text: "I'll be the actress starring in your bad dreams.", source: 'taylor', context: '"Blank Space" — 1989 (2014)', tone: 'threatening', intensity: 4, ambiguityScore: 8, commentary: "A haunting. Delivered with a smile." },
  { id: 't031', text: "I've got a list of names and yours is in red underlined.", source: 'taylor', context: '"Look What You Made Me Do" — Reputation (2017)', tone: 'vengeful', intensity: 5, ambiguityScore: 9, commentary: "She literally keeps lists. The most mafia behavior Taylor has admitted to." },
  { id: 't032', text: "You made me do it. You made me cruel.", source: 'taylor', context: '"You\'re On Your Own, Kid" — Midnights (2022)', tone: 'vengeful', intensity: 4, ambiguityScore: 8, commentary: "Blame shifted. The classic villain origin story." },
  { id: 't033', text: "I had the time of my life fighting dragons with you.", source: 'taylor', context: '"Long Live" — Speak Now (2010)', tone: 'loyalty', intensity: 4, ambiguityScore: 6, commentary: "Battle comrades. The inner circle who were there when it was hard." },
  { id: 't034', text: "I once believed love would be burning red.", source: 'taylor', context: '"Red" — Red (2012)', tone: 'heartbreak', intensity: 4, ambiguityScore: 3, commentary: "Color-coded heartbreak. Taylor's most cinematic thesis." },
  { id: 't035', text: "It was rare, I was there, I remember it all too well.", source: 'taylor', context: '"All Too Well (10 Minute Version)" — Red (Taylor\'s Version, 2021)', tone: 'heartbreak', intensity: 5, ambiguityScore: 4, commentary: "A memory kept alive with weaponized precision." },
  { id: 't036', text: "Nothing safe is worth the drive.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'chaotic', intensity: 2, ambiguityScore: 6, commentary: "Risk calculus. The Corleone family agrees." },
  { id: 't037', text: "I'd be a fearless leader. I'd be an alpha type.", source: 'taylor', context: '"The Man" — Lover (2019)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Articulating what she already is, in a different body." },
  { id: 't039', text: "In the middle of the night in my dreams you should see the things we do.", source: 'taylor', context: '"Style" — 1989 (2014)', tone: 'romantic', intensity: 3, ambiguityScore: 6, commentary: "Cryptic enough to belong to a crime family's night operations." },
  { id: 't040', text: "The ties were black, the lies were white.", source: 'taylor', context: '"Style" — 1989 (2014)', tone: 'betrayal', intensity: 3, ambiguityScore: 7, commentary: "Formal attire. Moral ambiguity. Sounds like a state dinner gone wrong." },
  { id: 't041', text: "I'm a mirrorball. I'll show you every version of yourself tonight.", source: 'taylor', context: '"Mirrorball" — Folklore (2020)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Reflective identity. Being whatever someone needs." },
  { id: 't044', text: "I'm the one who has to live with the choices I made.", source: 'taylor', context: '"This Is Me Trying" — Folklore (2020)', tone: 'heartbreak', intensity: 3, ambiguityScore: 5, commentary: "The weight of agency. Michael Corleone's entire personality, condensed." },
  { id: 't046', text: "Carve your name into my bedpost.", source: 'taylor', context: '"Dress" — Reputation (2017)', tone: 'romantic', intensity: 4, ambiguityScore: 5, commentary: "Intense, possessive, slightly alarming." },
  { id: 't047', text: "I'm only up when you're not down. Don't wanna be your good time girl.", source: 'taylor', context: '"Holy Ground" — Red (2012)', tone: 'loyalty', intensity: 2, ambiguityScore: 4, commentary: "Partnership over performance. The truest love." },
  { id: 't048', text: "You called me up again just to break me like a promise.", source: 'taylor', context: '"All You Had To Do Was Stay" — 1989 (2014)', tone: 'betrayal', intensity: 3, ambiguityScore: 5, commentary: "Betrayal as pattern. The don knows this energy." },
  { id: 't049', text: "I knew you'd linger like a tattoo kiss.", source: 'taylor', context: '"Cornelia Street" — Lover (2019)', tone: 'romantic', intensity: 3, ambiguityScore: 4, commentary: "Love as permanent marking. Permanence as power." },
  { id: 't050', text: "I'll be the one if you're looking for me.", source: 'taylor', context: '"King of My Heart" — Reputation (2017)', tone: 'romantic', intensity: 2, ambiguityScore: 3, commentary: "A simple promise. Even in the mob, they exist." },
  { id: 't051', text: "Long live all the mountains we moved, I had the time of my life fighting dragons with you.", source: 'taylor', context: '"Long Live" — Speak Now (2010)', tone: 'loyalty', intensity: 4, ambiguityScore: 6, commentary: "Epic loyalty. The stuff families are built on." },
  { id: 't052', text: "I'm getaway car. I'm a shot in the dark.", source: 'taylor', context: '"Getaway Car" — Reputation (2017)', tone: 'chaotic', intensity: 4, ambiguityScore: 7, commentary: "Vehicle and weapon. The perfect mob metaphor." },
  { id: 't054', text: "They say I did something bad. Then why does it feel so good?", source: 'taylor', context: '"I Did Something Bad" — Reputation (2017)', tone: 'chaotic', intensity: 4, ambiguityScore: 7, commentary: "The thrill of transgression. Honestly relatable." },
  { id: 't055', text: "There is nothing I do better than revenge.", source: 'taylor', context: '"Better Than Revenge" — Speak Now (2010)', tone: 'vengeful', intensity: 5, ambiguityScore: 8, commentary: "A self-assessment delivered with absolute certainty." },
  { id: 't056', text: "I'll be cleaning up bottles with you on New Year's Day.", source: 'taylor', context: '"New Year\'s Day" — Reputation (2017)', tone: 'loyalty', intensity: 2, ambiguityScore: 2, commentary: "Domestic loyalty after chaos. The quietest love declaration." },
  { id: 't057', text: "Peter was twenty-three when I met him at the door.", source: 'taylor', context: '"Peter" — The Tortured Poets Department (2024)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "Narrative precision. Names, ages, locations. Testimony." },
  { id: 't058', text: "We could leave the Christmas lights up 'til January.", source: 'taylor', context: '"Evermore" — Evermore (2020)', tone: 'heartbreak', intensity: 3, ambiguityScore: 2, commentary: "The saddest sentence about decorations ever written." },
  { id: 't061', text: "Everything has changed and nothing has.", source: 'taylor', context: '"Everything Has Changed" — Red (2012)', tone: 'romantic', intensity: 2, ambiguityScore: 4, commentary: "The paradox of transformation. Philosophical in any context." },
  { id: 't063', text: "I'm not the one you should be afraid of.", source: 'taylor', context: '"Who\'s Afraid of Little Old Me?" — TTPD (2024)', tone: 'threatening', intensity: 4, ambiguityScore: 9, commentary: "The most dangerous statement anyone can make." },
  { id: 't065', text: "I knew from the first note I'd be sick of you.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'chaotic', intensity: 3, ambiguityScore: 6, commentary: "Self-awareness arriving too late. The classic trap." },
  { id: 't066', text: "All the boys and all their expensive cars.", source: 'taylor', context: '"22" — Red (2012)', tone: 'chaotic', intensity: 2, ambiguityScore: 3, commentary: "Fleet vehicles. Could be rich boys. Could be the Corleone car pool." },
  { id: 't067', text: "You belong with me. You belong with me.", source: 'taylor', context: '"You Belong With Me" — Fearless (2008)', tone: 'romantic', intensity: 2, ambiguityScore: 2, commentary: "Insistent possession. Delivered from a different window." },
  { id: 't068', text: "I'd be an alpha type. Fearless leader.", source: 'taylor', context: '"The Man" — Lover (2019)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "She already is. She's just noting the double standard." },
  { id: 't072', text: "I knew you were trouble but I knew it wasn't enough to stay away.", source: 'taylor', context: '"I Knew You Were Trouble" — Red (2012)', tone: 'chaotic', intensity: 3, ambiguityScore: 5, commentary: "The confession of someone who makes bad choices brilliantly." },
  { id: 't073', text: "People like you always want back the love they gave away.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "A diagnosis delivered calmly. Clinical. Devastating." },
  { id: 't074', text: "I'm shaking at the thought of roaming clean without you.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'heartbreak', intensity: 3, ambiguityScore: 3, commentary: "Withdrawal as love. The most honest addiction metaphor." },
  { id: 't075', text: "The stakes are too high for you to stay.", source: 'taylor', context: '"Peace" — Folklore (2020)', tone: 'heartbreak', intensity: 4, ambiguityScore: 7, commentary: "Sacrifice delivered quietly. The highest stakes." },
  { id: 't077', text: "It's a love story. Baby, just say yes.", source: 'taylor', context: '"Love Story" — Fearless (2008)', tone: 'romantic', intensity: 2, ambiguityScore: 1, commentary: "The most clearly Taylor thing on this entire list." },
  { id: 't078', text: "Who you are is not who you were.", source: 'taylor', context: '"Long Story Short" — Evermore (2020)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Transformation as identity. The don understands this completely." },
  { id: 't079', text: "I loved you in spite of deep fears that the world would divide us.", source: 'taylor', context: '"Cornelia Street" — Lover (2019)', tone: 'romantic', intensity: 3, ambiguityScore: 6, commentary: "Loving across enemy lines. Star-crossed or rival families." },
  { id: 't080', text: "This ain't for the best. My reputation's never been worse. So you must like me for me.", source: 'taylor', context: '"Delicate" — Reputation (2017)', tone: 'romantic', intensity: 3, ambiguityScore: 5, commentary: "Love found in the rubble of a destroyed reputation." },
  { id: 't082', text: "You have always been the one. You are the only one.", source: 'taylor', context: '"Ours" — Speak Now (2010)', tone: 'romantic', intensity: 2, ambiguityScore: 2, commentary: "The clearest declaration of love in the catalog." },
  { id: 't083', text: "People throw rocks at things that shine.", source: 'taylor', context: '"Ours" — Speak Now (2010)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Envy as the price of excellence. The don knew this too." },
  { id: 't084', text: "I know I'm probably not your first.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'romantic', intensity: 2, ambiguityScore: 3, commentary: "Vulnerability offered despite the risk." },
  { id: 't085', text: "Someday I'll be big enough that you can't hit me.", source: 'taylor', context: '"Mean" — Speak Now (2011)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The long game. Revenge through becoming untouchable." },
  { id: 't086', text: "You are somebody that I don't know. Don't want to know.", source: 'taylor', context: '"Don\'t You" — Speak Now deluxe (2010)', tone: 'betrayal', intensity: 3, ambiguityScore: 5, commentary: "The final severance. Cutting off recognition entirely." },
  { id: 't088', text: "You were Romeo, I was a scarlet letter.", source: 'taylor', context: '"Love Story" — Fearless (2008)', tone: 'romantic', intensity: 2, ambiguityScore: 4, commentary: "Literary framing for young love. Two references in one." },
  { id: 't089', text: "Now you mail back my things and I walk home alone.", source: 'taylor', context: '"Last Kiss" — Speak Now (2010)', tone: 'heartbreak', intensity: 3, ambiguityScore: 2, commentary: "The logistics of loss. A breakup in one sentence." },
  { id: 't090', text: "Standing in a nice dress, staring at the sunset. Red lips, classic, in your arms.", source: 'taylor', context: '"Style" — 1989 (2014)', tone: 'romantic', intensity: 2, ambiguityScore: 2, commentary: "Pure cinematic romance. Nothing threatening here at all." },
  { id: 't092', text: "I hope you know that every time I don't, I almost do.", source: 'taylor', context: '"I Almost Do" — Red (2012)', tone: 'heartbreak', intensity: 3, ambiguityScore: 3, commentary: "Restraint as the most painful act." },
  { id: 't093', text: "I had the best days with you.", source: 'taylor', context: '"The Best Day" — Fearless (2008)', tone: 'family', intensity: 2, ambiguityScore: 2, commentary: "Pure. Clean. Not ambiguous at all." },
  { id: 't095', text: "We are too young to know it gets better.", source: 'taylor', context: '"Never Grow Up" — Speak Now (2010)', tone: 'heartbreak', intensity: 2, ambiguityScore: 2, commentary: "Youth as limitation. Knowledge as the only way out." },
  { id: 't097', text: "So casually cruel in the name of being honest.", source: 'taylor', context: '"All Too Well (10 Minute Version)" — Red (Taylor\'s Version, 2021)', tone: 'betrayal', intensity: 4, ambiguityScore: 5, commentary: "Honesty weaponized. The most sophisticated cruelty." },
  { id: 't098', text: "You kept me like a secret but I kept you like an oath.", source: 'taylor', context: '"All Too Well (10 Minute Version)" — Red (Taylor\'s Version, 2021)', tone: 'betrayal', intensity: 4, ambiguityScore: 7, commentary: "The asymmetry of loyalty. One kept a secret, one kept an oath." },
  { id: 't099', text: "Autumn leaves falling down like pieces into place.", source: 'taylor', context: '"All Too Well" — Red (2012)', tone: 'heartbreak', intensity: 3, ambiguityScore: 3, commentary: "Seasonal metaphor for things falling apart beautifully." },
  { id: 't100', text: "You call me up again just to break me like a promise.", source: 'taylor', context: '"All You Had To Do Was Stay" — 1989 (2014)', tone: 'betrayal', intensity: 3, ambiguityScore: 5, commentary: "The repeat offender. The don keeps track of these." },
  { id: 't103', text: "I know I'm gonna be okay. That doesn't mean I'm not afraid.", source: 'taylor', context: "\"Soon You'll Get Better\" — Lover (2019)", tone: 'heartbreak', intensity: 4, ambiguityScore: 3, commentary: "Courage named plainly. Admitting the fear." },
  { id: 't104', text: "Who are you? Who are you? I don't recognize you anymore.", source: 'taylor', context: '"Come Back...Be Here" — Red (2012)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "Identity lost through absence. The grieving that asks questions." },
  { id: 't107', text: "All the king's horses and all the king's men couldn't put me back together again.", source: 'taylor', context: '"The Archer" — Lover (2019)', tone: 'heartbreak', intensity: 4, ambiguityScore: 4, commentary: "Power unable to heal what love broke." },
  { id: 't110', text: "You should've said no.", source: 'taylor', context: '"Should\'ve Said No" — Taylor Swift (2006)', tone: 'vengeful', intensity: 3, ambiguityScore: 4, commentary: "Accountability delivered from a position of moral authority." },
  { id: 't111', text: "I'm not afraid of any of them. I'm afraid of letting them see that.", source: 'taylor', context: '"The Archer" — Lover (2019)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The real fear: being seen as afraid. The don's permanent state." },
  { id: 't114', text: "My castle crumbled overnight. I brought a knife to a gunfight.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'heartbreak', intensity: 4, ambiguityScore: 7, commentary: "Strategic failure. Outgunned. The cost of underestimating." },
  { id: 't116', text: "If he's a ghost then I can be a phantom.", source: 'taylor', context: '"...Ready For It?" — Reputation (2017)', tone: 'threatening', intensity: 4, ambiguityScore: 8, commentary: "Matching the energy of what haunts you. Power through mimicry." },
  { id: 't117', text: "You were my crown. Now you're the one who put me underground.", source: 'taylor', context: '"Haunted" — Speak Now (2010)', tone: 'betrayal', intensity: 4, ambiguityScore: 7, commentary: "Elevation to burial. The complete arc of betrayal." },
  { id: 't121', text: "We were built to fall apart, then fall back together.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'chaotic', intensity: 3, ambiguityScore: 5, commentary: "Dysfunction as architecture. Designed to cycle." },
  { id: 't122', text: "I see how this is going to end.", source: 'taylor', context: '"This Is Why We Can\'t Have Nice Things" — Reputation (2017)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Prescience. The don always sees the ending before it arrives." },
  { id: 't123', text: "Darling I'm a nightmare dressed like a daydream.", source: 'taylor', context: '"Blank Space" — 1989 (2014)', tone: 'chaotic', intensity: 4, ambiguityScore: 7, commentary: "Self-awareness as seduction. The best kind of warning." },
  { id: 't125', text: "We're all just standing in the rain but you made me a shelter.", source: 'taylor', context: '"Daylight" — Lover (2019)', tone: 'romantic', intensity: 2, ambiguityScore: 2, commentary: "Protection as love. The fundamental promise." },
  { id: 't126', text: "I don't want to keep secrets just to keep you.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'loyalty', intensity: 3, ambiguityScore: 5, commentary: "Transparency over possession. Very un-mob, very Taylor." },
  { id: 't128', text: "You had me believing every word till I found out you were my enemy.", source: 'taylor', context: '"Bad Blood" — 1989 (2014)', tone: 'betrayal', intensity: 4, ambiguityScore: 6, commentary: "The discovery of betrayal. The moment trust collapses." },
  { id: 't130', text: "You're the one I want. And that's the problem.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'chaotic', intensity: 3, ambiguityScore: 5, commentary: "Desire as liability. The complication that undoes everything." },
  { id: 't131', text: "We're happy free confused and lonely at the same time.", source: 'taylor', context: '"22" — Red (2012)', tone: 'chaotic', intensity: 2, ambiguityScore: 3, commentary: "The emotional chaos of youth. Absolutely unambiguous." },
  { id: 't133', text: "I'm a mess but I'm the mess that you wanted.", source: 'taylor', context: '"Holy Ground" — Red (2012)', tone: 'romantic', intensity: 2, ambiguityScore: 3, commentary: "Chosen disorder. Being loved in full, flaws included." },
  { id: 't134', text: "Do you remember all the city lights on the water?", source: 'taylor', context: '"This Love" — 1989 (2014)', tone: 'heartbreak', intensity: 2, ambiguityScore: 3, commentary: "Memory as haunting. The specific detail that won't leave." },
  { id: 't135', text: "I was in my element, no one else around.", source: 'taylor', context: '"False God" — Lover (2019)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Natural habitat. Power in solitude before the choice to share it." },
  { id: 't136', text: "Karma is the thunder rattling your cage.", source: 'taylor', context: '"Karma" — Midnights (2022)', tone: 'vengeful', intensity: 4, ambiguityScore: 7, commentary: "Cosmic accountability coming for you. On a schedule." },
  { id: 't137', text: "Karma's a relaxing thought. Aren't you envious that for you it's not?", source: 'taylor', context: '"Karma" — Midnights (2022)', tone: 'vengeful', intensity: 4, ambiguityScore: 8, commentary: "The don would understand this intimately. Karma arrives for others." },
  { id: 't138', text: "Did all the dominoes fall and land just right?", source: 'taylor', context: '"Mastermind" — Midnights (2022)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The mastermind reviewing the plan's execution." },
  { id: 't139', text: "It was all by design. Because I'm a mastermind.", source: 'taylor', context: '"Mastermind" — Midnights (2022)', tone: 'power', intensity: 5, ambiguityScore: 8, commentary: "The confession at the end. Everything was planned." },
  { id: 't140', text: "Everyone you've trusted seems to want to break you.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'betrayal', intensity: 4, ambiguityScore: 6, commentary: "The pattern recognition that arrives too late." },
  { id: 't141', text: "I once believed love would be burning red but it's golden.", source: 'taylor', context: '"Daylight" — Lover (2019)', tone: 'heartbreak', intensity: 3, ambiguityScore: 3, commentary: "The revision of expectations. Growth." },
  { id: 't142', text: "You're still all over me like a wine-stained dress I can't wear anymore.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "Stained and unwearable. The evidence that won't wash out." },
  { id: 't143', text: "I forgot that you existed.", source: 'taylor', context: '"I Forgot That You Existed" — Lover (2019)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Indifference as the ultimate revenge." },
  { id: 't144', text: "Now I see everything I ever needed was you.", source: 'taylor', context: '"You Are In Love" — 1989 (2014)', tone: 'romantic', intensity: 3, ambiguityScore: 3, commentary: "Pure love. No subtext. Even the Corleones had these moments." },
  { id: 't145', text: "You had me fighting for my life.", source: 'taylor', context: '"...Ready For It?" — Reputation (2017)', tone: 'threatening', intensity: 4, ambiguityScore: 7, commentary: "Existential stakes. Fighting for life either way." },
  { id: 't146', text: "They see right through me. Can you see me?", source: 'taylor', context: '"The Archer" — Lover (2019)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "The desire to be truly seen. The deepest vulnerability." },
  { id: 't147', text: "I'm the one who's gonna find you in the end.", source: 'taylor', context: '"I Know Places" — 1989 (2014)', tone: 'threatening', intensity: 4, ambiguityScore: 8, commentary: "Either a love promise or a threat. Impossible to tell which." },
  { id: 't148', text: "We run, we hide. They'll never find us.", source: 'taylor', context: '"I Know Places" — 1989 (2014)', tone: 'chaotic', intensity: 3, ambiguityScore: 7, commentary: "Fugitive energy. Two people on the run. From whom?" },
  { id: 't149', text: "I'll pay for this. I'll pay for this.", source: 'taylor', context: '"Red" — Red (2012)', tone: 'chaotic', intensity: 3, ambiguityScore: 5, commentary: "The awareness of cost before committing anyway." },
  { id: 't150', text: "Don't blame me, love made me crazy.", source: 'taylor', context: '"Don\'t Blame Me" — Reputation (2017)', tone: 'chaotic', intensity: 4, ambiguityScore: 6, commentary: "Love as an insanity plea. Accepted in both courts." },
  { id: 't152', text: "I let myself believe the fairy tale. That was my mistake.", source: 'taylor', context: '"The Story of Us" — Speak Now (2010)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "Hope named as the liability it always was." },
  { id: 't153', text: "Even if it's a lie, say it will be alright.", source: 'taylor', context: '"Soon You\'ll Get Better" — Lover (2019)', tone: 'heartbreak', intensity: 4, ambiguityScore: 3, commentary: "Permission to be lied to comfortingly. The most human request." },
  { id: 't154', text: "My reputation's never been worse. So you must like me for me.", source: 'taylor', context: '"Delicate" — Reputation (2017)', tone: 'romantic', intensity: 3, ambiguityScore: 5, commentary: "Love stripped of reputation. The cleanest version of being chosen." },
  { id: 't157', text: "Don't say you love me. Just put your arms around me.", source: 'taylor', context: '"Holy Ground" — Red (2012)', tone: 'romantic', intensity: 2, ambiguityScore: 3, commentary: "Action over declaration. Show, don't tell." },
  { id: 't158', text: "I don't wanna be you anymore.", source: 'taylor', context: '"Clean" — 1989 (2014)', tone: 'heartbreak', intensity: 3, ambiguityScore: 4, commentary: "Identity rejection after love. Wanting to be erased." },
  { id: 't159', text: "I'm catastrophic. And you're a disaster.", source: 'taylor', context: '"Treacherous" — Red (2012)', tone: 'chaotic', intensity: 4, ambiguityScore: 6, commentary: "Two catastrophes choosing each other. The most honest romance." },
  { id: 't160', text: "My love had been frozen. Deep blue, but you painted me golden.", source: 'taylor', context: '"Daylight" — Lover (2019)', tone: 'romantic', intensity: 3, ambiguityScore: 3, commentary: "Transformation by love. The thawing of a defended heart." },
  { id: 't161', text: "I've cleaned enough houses to know how to cover up a scene.", source: 'taylor', context: '"No Body, No Crime" (feat. HAIM) — folklore (2020)', tone: 'threatening', intensity: 5, ambiguityScore: 9, commentary: "A true crime lyric disguised as domestic detail. The most Godfather sentence on a folklore album." },
  { id: 't162', text: "Never be so kind you forget to be clever, never be so clever you forget to be kind.", source: 'taylor', context: '"Marjorie" — evermore (2020)', tone: 'loyalty', intensity: 3, ambiguityScore: 4, commentary: "Wisdom passed from grandmother to granddaughter. The don would agree with every word." },
  { id: 't163', text: "I'm only cryptic and Machiavellian because I care.", source: 'taylor', context: '"Mastermind" — Midnights (2022)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The most self-aware villain confession in pop music. Don Corleone also only did it because he cared." },
  { id: 't164', text: "Devils that you know raise worse hell than a stranger.", source: 'taylor', context: '"The Albatross" — The Tortured Poets Department: The Anthology (2024)', tone: 'threatening', intensity: 4, ambiguityScore: 7, commentary: "Wisdom about familiar enemies. The don kept his friends close for exactly this reason." },
  { id: 't165', text: "Their faith was strong but I pushed it too far.", source: 'taylor', context: '"Castles Crumbling" (feat. Hayley Williams) — Speak Now (Taylor\'s Version) (2023)', tone: 'betrayal', intensity: 4, ambiguityScore: 6, commentary: "Power outrunning loyalty. The exact mistake that brought down every empire." },
  { id: 't166', text: "Power went to my head and I couldn't stop.", source: 'taylor', context: '"Castles Crumbling" (feat. Hayley Williams) — Speak Now (Taylor\'s Version) (2023)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "The confession of unchecked ambition. Michael Corleone never said it aloud but felt it." },
  { id: 't167', text: "I am immortal now.", source: 'taylor', context: '"The Life of a Showgirl" (feat. Sabrina Carpenter) — The Life of a Showgirl (2025)', tone: 'power', intensity: 5, ambiguityScore: 7, commentary: "The ultimate power statement. Delivered over sequins and synthesizers." },
  { id: 't168', text: "I protect the family.", source: 'taylor', context: '"Father Figure" — The Life of a Showgirl (2025)', tone: 'family', intensity: 5, ambiguityScore: 10, commentary: "Three words that define the entire Corleone saga. Also apparently a pop chorus." },
  { id: 't169', text: "All I ask for is your loyalty, my dear protégé.", source: 'taylor', context: '"Father Figure" — The Life of a Showgirl (2025)', tone: 'power', intensity: 4, ambiguityScore: 10, commentary: "The don's only ask. Delivered in a different octave but with equal menace." },
  { id: 't170', text: "This empire belongs to me.", source: 'taylor', context: '"Father Figure" — The Life of a Showgirl (2025)', tone: 'power', intensity: 5, ambiguityScore: 9, commentary: "Stated without negotiation. The inheritance claimed." },
  { id: 't171', text: "Everyone's got bodies in the attic.", source: 'taylor', context: '"CANCELLED!" — The Life of a Showgirl (2025)', tone: 'threatening', intensity: 4, ambiguityScore: 9, commentary: "Mutual assured destruction theory. Somehow more reassuring than alarming." },
  { id: 't172', text: "A shattered glass is a lot more sharp.", source: 'taylor', context: '"CANCELLED!" — The Life of a Showgirl (2025)', tone: 'threatening', intensity: 4, ambiguityScore: 7, commentary: "Destruction as transformation. What breaks becomes dangerous." },
  { id: 't173', text: "Your home's really only a town you're just a guest in.", source: 'taylor', context: '"Florida!!!" (feat. Florence + The Machine) — The Tortured Poets Department (2024)', tone: 'heartbreak', intensity: 3, ambiguityScore: 5, commentary: "Belonging denied. The exile who never quite fits anywhere." },
  { id: 't174', text: "Old habits die screaming.", source: 'taylor', context: '"The Black Dog" — The Tortured Poets Department (2024)', tone: 'heartbreak', intensity: 4, ambiguityScore: 6, commentary: "The opposite of the cliché. Habits don't fade — they go out violently." },
  { id: 't175', text: "The family, the pure greed, the Christian chorus line.", source: 'taylor', context: '"Cassandra" — The Tortured Poets Department (2024)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Institution named as oppressor. The Corleones would recognize the category." },
  { id: 't176', text: "There's only so far new money goes.", source: 'taylor', context: '"the last great american dynasty" — folklore (2020)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Old money holds the high ground. A lesson in class warfare told through gossip." },
  { id: 't177', text: "It's obvious that wanting me dead has really brought you two together.", source: 'taylor', context: '"mad woman" — folklore (2020)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Dry observation of your own assassination plot. Unshakeable composure." },
  { id: 't178', text: "Family that I chose, now that I see your brother as my brother.", source: 'taylor', context: '"peace" — folklore (2020)', tone: 'loyalty', intensity: 3, ambiguityScore: 5, commentary: "Chosen family elevated to blood loyalty. The don would understand this completely." },
  { id: 't179', text: "Those eyes add insult to injury.", source: 'taylor', context: '"exile" (feat. Bon Iver) — folklore (2020)', tone: 'betrayal', intensity: 3, ambiguityScore: 4, commentary: "Betrayal compounded by beauty. The cruelest detail." },
  { id: 't180', text: "And all the pieces fall right into place.", source: 'taylor', context: '"So It Goes..." — reputation (2017)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "The plan completing itself. The mastermind watching dominoes fall." },
  { id: 't181', text: "It's never too late to come back to my side.", source: 'taylor', context: '"Dorothea" — evermore (2020)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "The open door that never really closed. Confidence dressed as generosity." },
  { id: 't182', text: "God smiles on my little brother.", source: 'taylor', context: '"The Best Day" — Fearless (2008)', tone: 'family', intensity: 2, ambiguityScore: 3, commentary: "Pure familial love. Uncomplicated. The Corleones had these moments too." },
  { id: 't183', text: "No one here's to blame, but what about your quiet treason.", source: 'taylor', context: '"Fortnight" (feat. Post Malone) — The Tortured Poets Department (2024)', tone: 'betrayal', intensity: 4, ambiguityScore: 7, commentary: "Treason named, blame withheld. The most sophisticated accusation." },
  { id: 't184', text: "Blood's thick, but nothing like a payroll.", source: 'taylor', context: '"Cassandra" — The Tortured Poets Department (2024)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "The mercenary truth about loyalty. Money beats blood in the final accounting." },
]

const godfatherQuotes: Quote[] = [
  { id: 'g001', text: "I'm gonna make him an offer he can't refuse.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'threatening', intensity: 5, ambiguityScore: 2, commentary: "The most famous mob line in cinema. If you got this wrong, we have concerns." },
  { id: 'g002', text: "Leave the gun. Take the cannoli.", source: 'godfather', context: 'Peter Clemenza — The Godfather (1972)', tone: 'chaotic', intensity: 3, ambiguityScore: 4, commentary: "Priorities. The dessert is more important than the evidence." },
  { id: 'g003', text: "It's not personal, Sonny. It's strictly business.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 5, commentary: "The coldest line in film history. Used in 40% of bad business decisions." },
  { id: 'g005', text: "The lawyer with the briefcase can steal more money than the man with the gun.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "Sophisticated criminality. Evolution from brute force to institutional power." },
  { id: 'g006', text: "Never hate your enemies. It affects your judgment.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Cold strategic wisdom. Detachment as a weapon." },
  { id: 'g007', text: "Keep your friends close but your enemies closer.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 5, ambiguityScore: 6, commentary: "The definitive strategic aphorism. Used in 40% of business school presentations." },
  { id: 'g008', text: "I spent my whole life trying not to be careless.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "Michael's tragic flaw announced early. Precision as identity." },
  { id: 'g009', text: "In Sicily, women are more dangerous than shotguns.", source: 'godfather', context: 'Calo — The Godfather (1972)', tone: 'chaotic', intensity: 3, ambiguityScore: 8, commentary: "High praise disguised as a warning. This is actually a compliment." },
  { id: 'g010', text: "Fredo, you're my older brother and I love you. But don't ever take sides against the Family again.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'family', intensity: 5, ambiguityScore: 5, commentary: "Love and threat in the same breath. The Corleone family motto." },
  { id: 'g011', text: "Power wears out those who do not have it.", source: 'godfather', context: 'Calo — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Insight that sounds like a keynote speech. Also mob operating principle." },
  { id: 'g012', text: "Friendship is everything. Friendship is more than talent. It is more than government. It is almost the equal of family.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'loyalty', intensity: 3, ambiguityScore: 7, commentary: "A philosophy of relationships that almost sounds inspirational. Almost." },
  { id: 'g013', text: "You talk about vengeance. Is vengeance going to bring your son back to you?", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "The don counseling restraint in grief. Wisdom from a man who understands cost." },
  { id: 'g014', text: "A man in my position cannot afford to be made to look ridiculous.", source: 'godfather', context: 'Don Altobello — The Godfather Part III (1990)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Reputation management as survival strategy." },
  { id: 'g015', text: "My father is no different than any powerful man, any man with power like a president or senator.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Normalization of power as Michael first begins to rationalize the family business." },
  { id: 'g016', text: "We are all responsible for what we do unless we are insane.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Accountability from the head of the most accountable-in-the-worst-way family." },
  { id: 'g017', text: "Every family has bad memories.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'family', intensity: 3, ambiguityScore: 8, commentary: "The understatement of the century." },
  { id: 'g018', text: "Just when I thought I was out, they pull me back in.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'heartbreak', intensity: 4, ambiguityScore: 6, commentary: "Michael trying to escape the life. It never lets go." },
  { id: 'g019', text: "I have a sentimental weakness for my children and I spoil them as you can see.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 2, ambiguityScore: 6, commentary: "The don's only acknowledged vulnerability. He loves without calculation." },
  { id: 'g020', text: "It's dangerous to be an honest man.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Wisdom about the structural disadvantage of virtue." },
  { id: 'g021', text: "You cannot say no to the people you love. Not often.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 3, ambiguityScore: 8, commentary: "Love as the weakness and the strength simultaneously." },
  { id: 'g022', text: "Revenge is a dish that tastes best when it is cold.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'vengeful', intensity: 4, ambiguityScore: 5, commentary: "Patience as a weapon. The don never rushed." },
  { id: 'g023', text: "I work my whole life, I don't apologize, to take care of my family.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 4, ambiguityScore: 7, commentary: "The great justification. Everything done in the name of family." },
  { id: 'g024', text: "Some day and that day may never come I'll call upon you to do a service for me.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 5, ambiguityScore: 4, commentary: "The inciting contract. Casually binding. The don plays the long game." },
  { id: 'g025', text: "You can't hide what you are.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Identity as fate. Michael accepting what he is." },
  { id: 'g026', text: "There are things that have to be done and you do them and you never talk about them.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 5, ambiguityScore: 7, commentary: "Omerta explained. The code of silence." },
  { id: 'g027', text: "Don't ever take sides with anyone against the Family. Ever.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'loyalty', intensity: 5, ambiguityScore: 5, commentary: "The highest law. Spoken with the weight of everything." },
  { id: 'g028', text: "I believe in America.", source: 'godfather', context: 'Bonasera — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "The film's first line. A man confessing faith in a system that failed him." },
  { id: 'g029', text: "I ask you for justice.", source: 'godfather', context: 'Bonasera — The Godfather (1972)', tone: 'heartbreak', intensity: 4, ambiguityScore: 5, commentary: "The opening scene. A man seeking the only justice he believes in." },
  { id: 'g030', text: "You always told me never to trust anyone outside the family.", source: 'godfather', context: 'Sonny Corleone — The Godfather (1972)', tone: 'loyalty', intensity: 4, ambiguityScore: 6, commentary: "Loyalty as doctrine. The first lesson of Corleone childhood." },
  { id: 'g031', text: "This one time I'll let you ask me about my affairs.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Conditional transparency. The don grants exactly one exception." },
  { id: 'g032', text: "I'll reason with him.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'threatening', intensity: 4, ambiguityScore: 8, commentary: "The most terrifying offer of diplomacy in cinema. 'Reason' used very loosely." },
  { id: 'g033', text: "What I want, what's most important to me, is that I have a guarantee of safety for my family.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 4, ambiguityScore: 7, commentary: "Not power, not money. Safety. The deepest parental fear." },
  { id: 'g034', text: "We're not murderers, in spite of what this undertaker thinks.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'chaotic', intensity: 3, ambiguityScore: 5, commentary: "The distinction that matters most to the don. Businessmen, not murderers. Sort of." },
  { id: 'g036', text: "I want reliable people. People that aren't going to be carried away.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Talent acquisition. ROI-focused leadership." },
  { id: 'g037', text: "He never asks a second favor when he's been refused the first.", source: 'godfather', context: 'About Don Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Pride and precision. The don does not beg. Ever." },
  { id: 'g039', text: "We will not accept anything less than what we are owed.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Entitlement and dignity fused. What's owed is always more than offered." },
  { id: 'g040', text: "He's a man. There are men in this world who go about demanding to be killed.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Vito explaining a personality type with cold compassion." },
  { id: 'g042', text: "You have been a good friend. You have done a great service to the family.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'loyalty', intensity: 3, ambiguityScore: 6, commentary: "The highest praise available. Slightly ominous depending on context." },
  { id: 'g044', text: "We are all doomed to do penance for whatever we do.", source: 'godfather', context: 'Cardinal Lamberto — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Theological accountability. Even the clergy understand weight." },
  { id: 'g045', text: "You talk about vengeance. Is vengeance going to bring your son back to you or my boy to me?", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'heartbreak', intensity: 5, ambiguityScore: 5, commentary: "Grief beneath the power. The most powerful man weeping for his son." },
  { id: 'g049', text: "Behind every great fortune there is a crime.", source: 'godfather', context: 'Epigraph — The Godfather novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "Balzac via Puzo. The source of all wealth, explained." },
  { id: 'g050', text: "The only wealth in this world is children. More than all the money, power on earth, you are my treasure.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 4, ambiguityScore: 7, commentary: "The don's actual value system. Everything else is means, this is the end." },
  { id: 'g051', text: "I'm going to make this city an offer it can't refuse.", source: 'godfather', context: 'Young Vito Corleone — The Godfather Part II (1974)', tone: 'threatening', intensity: 5, ambiguityScore: 3, commentary: "Origin story. Young Vito coining the phrase." },
  { id: 'g052', text: "Don't be afraid, Charlie. Come on, you look terrible.", source: 'godfather', context: 'Don Corleone comforting — The Godfather (1972)', tone: 'family', intensity: 2, ambiguityScore: 5, commentary: "Tenderness from the don. He notices when you're suffering." },
  { id: 'g053', text: "You know, my father he loved music. He sang like a bird.", source: 'godfather', context: 'Vito Corleone — The Godfather Part II (1974)', tone: 'family', intensity: 2, ambiguityScore: 4, commentary: "The memory of beauty before everything changed." },
  { id: 'g054', text: "I don't feel I have to wipe everybody out, Tom. Just my enemies.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'threatening', intensity: 5, ambiguityScore: 6, commentary: "The most alarming use of the word 'just' in film history." },
  { id: 'g058', text: "Leave it alone. It's not personal.", source: 'godfather', context: 'Tom Hagen — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "The consigliere cooling heads. Business above feeling." },
  { id: 'g059', text: "My father taught me many things. He taught me to keep my friends close.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'family', intensity: 4, ambiguityScore: 6, commentary: "Inheritance of wisdom. The lessons passed through blood." },
  { id: 'g060', text: "Italians have a little joke. The world is so hard, how am I going to find a friend? Even if I find him, how do I know I can trust him?", source: 'godfather', context: 'Vito Corleone — The Godfather Part II (1974)', tone: 'loyalty', intensity: 3, ambiguityScore: 6, commentary: "The great problem of loyalty. Finding and trusting." },
  { id: 'g061', text: "You have to answer for Santino, Carlo.", source: 'godfather', context: 'Michael Corleone — The Godfather (1972)', tone: 'threatening', intensity: 5, ambiguityScore: 4, commentary: "Accountability delivered quietly. The calmest sentences are the most terrifying." },
  { id: 'g062', text: "A man who does not have his own land is nobody.", source: 'godfather', context: 'Vito Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Property as identity. Roots as power." },
  { id: 'g064', text: "Every man has but one destiny.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Fatalism as philosophy. You are what you are becoming." },
  { id: 'g066', text: "The man who can be trusted is the most valuable man alive.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'loyalty', intensity: 4, ambiguityScore: 7, commentary: "Trust as the scarcest resource. Valued above all else." },
  { id: 'g067', text: "I swear on the souls of my grandchildren that I will not be the one to break the peace.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'loyalty', intensity: 4, ambiguityScore: 5, commentary: "The deepest oath. Sworn on the next generation." },
  { id: 'g068', text: "Good health is the most important thing. More than success, more than money, more than power.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 3, ambiguityScore: 6, commentary: "The priority list reordered. Coming from a don, this lands differently." },
  { id: 'g070', text: "Time erodes gratitude more quickly than it does beauty.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 3, ambiguityScore: 8, commentary: "The decay of memory. Why loyalty must be maintained actively." },
  { id: 'g071', text: "Never let anyone know what you are thinking.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Opacity as armour. The first rule of the game." },
  { id: 'g072', text: "I have always believed helping your fellow man is profitable in every sense, personally and bottom line.", source: 'godfather', context: 'Michael Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Altruism reframed as strategy. Vito's genius." },
  { id: 'g073', text: "A long line of men came before you. Each made his own choices. The choice is yours.", source: 'godfather', context: 'Don Vito to Michael — Mario Puzo novel (1969)', tone: 'family', intensity: 4, ambiguityScore: 7, commentary: "Legacy as invitation. The burden of choice." },
  { id: 'g074', text: "No one will ever love you as I do. No one.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'family', intensity: 5, ambiguityScore: 7, commentary: "Possessive love. The don's deepest truth." },
  { id: 'g076', text: "You cannot refuse what was given to you by your blood.", source: 'godfather', context: 'Vito Corleone — Mario Puzo novel (1969)', tone: 'family', intensity: 4, ambiguityScore: 7, commentary: "Legacy as obligation. What blood gives, you cannot return." },
  { id: 'g080', text: "You have to be careful of the men who smile too much.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'threatening', intensity: 3, ambiguityScore: 7, commentary: "The con man's tell. Excessive warmth as warning signal." },
  { id: 'g081', text: "I've done things. I'm not proud of them. But I did them. And I would do them again.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Ownership without apology. The hardest kind of honesty." },
  { id: 'g082', text: "You can have anything in this world with money. But you cannot buy a minute of time.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The limit of power. Time as the only true scarcity." },
  { id: 'g085', text: "My father once told me: don't hate your enemy, it clouds your thinking.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Inherited wisdom. The strategic cost of hatred." },
  { id: 'g086', text: "I never wanted this life for you, Michael. There is nothing sadder than a wasted life.", source: 'godfather', context: 'Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 5, ambiguityScore: 7, commentary: "The father's regret. What he built destroyed what he loved." },
  { id: 'g088', text: "The dead are dead. It's the living who matter.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Ruthless pragmatism. Grief as a luxury you cannot afford." },
  { id: 'g090', text: "You were always the smarter one. I always knew that.", source: 'godfather', context: 'Vito Corleone to Michael — Mario Puzo novel (1969)', tone: 'family', intensity: 3, ambiguityScore: 6, commentary: "The father's recognition. Given too late, as always." },
  { id: 'g091', text: "A man has to have something to live for, otherwise he becomes dangerous.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'threatening', intensity: 4, ambiguityScore: 8, commentary: "Purpose as the thing keeping the dangerous man contained." },
  { id: 'g093', text: "You've been leading a double life. That's not unusual in our world.", source: 'godfather', context: 'Tom Hagen — The Godfather (1972)', tone: 'chaotic', intensity: 3, ambiguityScore: 7, commentary: "Normalizing duplicity. In this world, it is simply what is done." },
  { id: 'g099', text: "You carry a scar, it means you survived.", source: 'godfather', context: 'Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Wounds as proof. Evidence of having come through." },
  { id: 'g100', text: "Some men are not meant to be alone. They need someone at their side forever.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'romantic', intensity: 3, ambiguityScore: 6, commentary: "The don on partnership. Softer than expected." },
  { id: 'g107', text: "I ask for nothing. But when I need something, I remember who helped and who didn't.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "The long memory. Generosity and ledger-keeping coexist." },
  { id: 'g109', text: "You cannot win a war unless you know what you are fighting for.", source: 'godfather', context: 'Don Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Purpose as prerequisite. Fighting without cause is just violence." },
  { id: 'g110', text: "My greatest mistake was teaching you to be kind. I should have taught you to be feared.", source: 'godfather', context: 'Don Vito to Sonny — Mario Puzo novel (1969)', tone: 'family', intensity: 5, ambiguityScore: 7, commentary: "Regret as inheritance. What love withheld in the name of goodness." },
  { id: 'g112', text: "The man who gives the order does not pull the trigger. But he is not innocent.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 5, ambiguityScore: 6, commentary: "Moral culpability at a distance. The architecture of power." },
  { id: 'g117', text: "I have made my peace with what I am. I ask only that others do the same.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Acceptance without apology. The final stage of the journey." },
  { id: 'g120', text: "People only hear what they are prepared to hear.", source: 'godfather', context: 'Tom Hagen — Mario Puzo novel (1969)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "The limit of communication. Readiness determines reception." },
  { id: 'g122', text: "Everything I built, I built for you. And that may have been my greatest cruelty.", source: 'godfather', context: 'Vito Corleone — Mario Puzo novel (1969)', tone: 'family', intensity: 5, ambiguityScore: 7, commentary: "Love as burden. The legacy that traps rather than liberates." },
  { id: 'g123', text: "Do not mourn what you have lost. Protect what remains.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Grief redirected to action. The strategic response to loss." },
  { id: 'g126', text: "What is done cannot be undone. But it can be answered for.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Accountability as the only response to irreversibility." },
  { id: 'g127', text: "A woman is not property. But a man who loves a woman is.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'romantic', intensity: 3, ambiguityScore: 7, commentary: "Love's strange reversal. The one who loves surrenders the most." },
  { id: 'g128', text: "In the end we all face the same judge. And he does not care how powerful you were.", source: 'godfather', context: 'Cardinal Lamberto — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "Divine justice as the great equalizer." },
  { id: 'g129', text: "A man who lies to himself cannot lie successfully to anyone else.", source: 'godfather', context: 'Don Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Internal dishonesty as the root of all strategic failure." },
  { id: 'g131', text: "There is no escaping what you are. You can only choose what you do with it.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Identity as fixed, action as variable. The only freedom." },
  { id: 'g133', text: "To be generous is to be powerful.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 7, commentary: "Vito's genius. Giving as the act that creates the most obligation." },
  { id: 'g134', text: "The worst things I ever did, I did for love.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'family', intensity: 5, ambiguityScore: 8, commentary: "The confession beneath everything. Love as the ultimate justification." },
  { id: 'g135', text: "If your father had lived, things would have been very different.", source: 'godfather', context: 'Tom Hagen — The Godfather (1972)', tone: 'heartbreak', intensity: 3, ambiguityScore: 5, commentary: "The pivot point of grief. The counterfactual that never leaves." },
  { id: 'g136', text: "You will never be alone again. That I promise you.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'loyalty', intensity: 4, ambiguityScore: 7, commentary: "The unconditional promise. The don never made one he didn't keep." },
  { id: 'g138', text: "The day I lose my anger is the day I lose my edge.", source: 'godfather', context: 'Sonny Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Anger as fuel. Sonny's philosophy that also explained his downfall." },
  { id: 'g139', text: "Everything you love will eventually be taken from you. The question is what you do while you still have it.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'heartbreak', intensity: 5, ambiguityScore: 7, commentary: "Loss as the only certainty. Action as the only response." },
  { id: 'g142', text: "When your enemy is afraid, show him kindness. Fear will turn to loyalty.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "The alchemy of power. Turning fear into something more durable." },
  { id: 'g143', text: "I did not come to this country to live poor. I came to live well.", source: 'godfather', context: 'Young Vito Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "The immigrant's ambition stated plainly. The beginning of everything." },
  { id: 'g144', text: "Every time I tried to get out, the thing I loved most pulled me back.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'heartbreak', intensity: 5, ambiguityScore: 7, commentary: "The trap of love. What you cannot leave because of what you feel." },
  { id: 'g147', text: "Anyone who underestimated you will regret it. I have never made that mistake.", source: 'godfather', context: 'Tom Hagen to Michael — Mario Puzo novel (1969)', tone: 'loyalty', intensity: 4, ambiguityScore: 7, commentary: "The gift of being truly seen. By the one who stood beside you." },
  { id: 'g148', text: "Do what must be done. Regret it later if you like. But do it.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Action before feeling. Grief as a scheduled appointment." },
  { id: 'g149', text: "The world you were born into is not the world you must die in.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The possibility of transformation. The immigrant's fundamental belief." },
  { id: 'g150', text: "You cannot truly love what you do not truly know.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'romantic', intensity: 3, ambiguityScore: 7, commentary: "Knowledge as prerequisite for love. The don on intimacy." },
  { id: 'g153', text: "The man who fears nothing loves nothing.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'romantic', intensity: 3, ambiguityScore: 7, commentary: "Fear as proof of love. Vulnerability as evidence of caring." },
  { id: 'g154', text: "I want you to understand that whatever I do, I do for the family. Always.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'family', intensity: 4, ambiguityScore: 6, commentary: "The endless justification. Family as both reason and shield." },
  { id: 'g155', text: "Your suffering is noted. And it will be answered.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'loyalty', intensity: 5, ambiguityScore: 8, commentary: "Justice promised without timeline. The most powerful kind of promise." },
  { id: 'g156', text: "I never ask for anything. I only remind people of what they owe.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "The don's distinctive ask. Not a request but a reminder." },
  { id: 'g157', text: "A man must choose either power or peace. He cannot have both.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'heartbreak', intensity: 5, ambiguityScore: 7, commentary: "The cost Michael finally understood. The choice he made without knowing." },
  { id: 'g158', text: "I kept my mouth shut and that's how I got this far.", source: 'godfather', context: 'Vito Corleone — The Godfather Part II (1974)', tone: 'power', intensity: 3, ambiguityScore: 6, commentary: "Silence as strategy. The most underrated skill in any room." },
  { id: 'g159', text: "There is always a price. The only question is who pays it and when.", source: 'godfather', context: 'Michael Corleone — Mario Puzo novel (1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Cost as inevitability. Power does not eliminate the price tag." },
  { id: 'g160', text: "In my world, the ones who love you are the ones who stay when everything falls apart.", source: 'godfather', context: 'Don Vito Corleone — Mario Puzo novel (1969)', tone: 'loyalty', intensity: 4, ambiguityScore: 7, commentary: "The loyalty test that only crisis reveals." },
  { id: 'g161', text: "If anything in this life is certain, if history has taught us anything, it is that you can kill anyone.", source: 'godfather', context: 'Michael Corleone — The Godfather Part II (1974)', tone: 'threatening', intensity: 5, ambiguityScore: 5, commentary: "The most chilling strategic insight in the trilogy. Spoken with the calmness of someone who means it." },
  { id: 'g162', text: "You can act like a man.", source: 'godfather', context: 'Don Vito Corleone to Johnny Fontane — The Godfather (1972)', tone: 'power', intensity: 3, ambiguityScore: 5, commentary: "Vito dismissing self-pity in five words. The shortest lesson in the film." },
  { id: 'g163', text: "I made my bones while you were going out with cheerleaders.", source: 'godfather', context: 'Moe Greene — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "Earned authority versus inherited power. Moe Greene's last confident statement before everything changed." },
  { id: 'g164', text: "Your enemies always get strong on what you leave behind.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "Abandonment as armament. Everything you walk away from becomes their weapon." },
  { id: 'g165', text: "A man who doesn't spend time with his family can never be a real man.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 3, ambiguityScore: 6, commentary: "The don's definition of manhood. Said at his daughter's wedding while conducting mob business." },
  { id: 'g166', text: "A friend should always underestimate your virtues and an enemy overestimate your faults.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 3, ambiguityScore: 8, commentary: "Strategic humility and strategic paranoia in one sentence. The complete playbook." },
  { id: 'g167', text: "I don't trust society to protect us. I have no intention of placing my fate in the hands of men whose only qualification is that they managed to get a block of people to vote for them.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 4, ambiguityScore: 6, commentary: "The don's political philosophy stated plainly. Describes approximately 40% of modern voters." },
  { id: 'g168', text: "Accidents don't happen to people who take accidents as a personal insult.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 4, ambiguityScore: 8, commentary: "Paranoia reframed as diligence. The don's safety record speaks for itself." },
  { id: 'g169', text: "They call it business. But it's personal as hell.", source: 'godfather', context: 'Sonny Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 4, ambiguityScore: 7, commentary: "The inversion of Michael's most famous line. The consigliere knew what Michael pretended he didn't." },
  { id: 'g170', text: "If I can die saying life is so beautiful, then nothing else is important.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'family', intensity: 4, ambiguityScore: 6, commentary: "The don's actual credo. Behind all the power, this is what he was protecting." },
  { id: 'g171', text: "If I wanted you dead, you'd be dead already.", source: 'godfather', context: 'Virgil Sollozzo — The Godfather (1972)', tone: 'threatening', intensity: 5, ambiguityScore: 4, commentary: "The most terrifying reassurance in cinema. Not comfort — just math." },
  { id: 'g172', text: "When they come, they come at what you love.", source: 'godfather', context: 'Michael Corleone — The Godfather Part III (1990)', tone: 'threatening', intensity: 5, ambiguityScore: 7, commentary: "The strategic targeting of affection. Love is the only real vulnerability." },
  { id: 'g173', text: "The strength of a family, like the strength of an army, lies in its loyalty to each other.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (novel, 1969)', tone: 'loyalty', intensity: 4, ambiguityScore: 6, commentary: "The structural theory of the Corleone empire. Military metaphor applied to blood." },
  { id: 'g174', text: "Women and children can afford to be careless, men cannot.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (1972)', tone: 'power', intensity: 4, ambiguityScore: 5, commentary: "Vito's worldview encoded in a single sentence. The burden and the privilege of being a man in his world." },
  { id: 'g175', text: "Forgive, forget. Life is full of misfortunes.", source: 'godfather', context: 'Don Vito Corleone — The Godfather (novel, 1969)', tone: 'power', intensity: 2, ambiguityScore: 6, commentary: "Grace extended as philosophy. The don could be magnanimous when it cost him nothing." },
]

export const ALL_QUOTES: Quote[] = [...taylorQuotes, ...godfatherQuotes]

export function shuffleQuotes(quotes: Quote[], seed?: number): Quote[] {
  const arr = [...quotes]
  let currentSeed = seed ?? Date.now()
  const seededRandom = () => {
    currentSeed = (currentSeed * 1664525 + 1013904223) & 0xffffffff
    return (currentSeed >>> 0) / 0x100000000
  }
  const rng = seed !== undefined ? seededRandom : Math.random
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]]
  }
  return arr
}

export function getDailyQuotes(): Quote[] {
  const today = new Date()
  const seed = today.getFullYear() * 10000 + (today.getMonth() + 1) * 100 + today.getDate()
  return shuffleQuotes(ALL_QUOTES, seed).slice(0, 10)
}

